(function(root,factory){if(typeof module==='object')module.exports=factory();else root.DragonEngine=factory()})(typeof window==='object'?window:this,()=>{
const learning=()=>typeof ArcadeLearning!=='undefined'?ArcadeLearning:(typeof window!=='undefined'?window.ArcadeLearning:null);function recordPractice(owner,correct,timeout=false){const api=learning(),q=owner.question;if(!api?.active||!q||q.completed||owner.practiceAnsweredQuestion===q)return false;owner.practiceAnsweredQuestion=q;api.record(q,correct,undefined,{timeout});return true;}
class Flight{
 constructor(o={}){this.random=o.random||Math.random;this.timed=!!o.timed;this.op=o.operation||'add';this.range=o.range||10;this.total=this.timed?Infinity:12;this.passed=0;this.hearts=3;this.streak=0;this.charge=0;this.coins=0;this.level=1;this.x=.5;this.y=.5;this.targetX=.5;this.time=0;this.elapsed=0;this.duration=5.5;this.ready=false;this.cooldown=0;this.active=true;this.power=false;this.events=[];this.enemies=[];this.shots=[];this.enemyId=0;this.shotId=0;this.question=this.makeQuestion();this.fillEnemies(true)}
 makeQuestion(){if(learning()?.active)return learning().next();const a=1+Math.floor(this.random()*this.range),b=1+Math.floor(this.random()*this.range),op=this.op==='mix'?['add','sub','mul','div'][Math.floor(this.random()*4)]:this.op;const answer=op==='add'?a+b:op==='mul'?a*b:b,text=op==='add'?a+' + '+b:op==='mul'?a+' × '+b:op==='sub'?(a+b)+' − '+a:(a*b)+' ÷ '+a;const values=new Set([answer]);for(const n of [answer+1,answer-1,answer+a,answer+b,answer+2,answer-2])if(n>=0&&values.size<4)values.add(n);while(values.size<4)values.add(answer+values.size);const choices=[...values];for(let i=choices.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]]}return{text,answer,choices}}
 fillEnemies(initial=false){while(this.enemies.length<Math.min(3,this.total-this.passed)){const index=this.enemies.length,lane=(this.enemyId++%3),x=Math.max(.15,Math.min(.85,.2+lane*.3+(this.random()-.5)*.1));this.enemies.push({id:this.enemyId,x,z:initial?index*.16:0,targeted:false})}}
 answer(value){if(this.question?.completed||!this.active||this.ready)return false;if(value!==this.question.answer){recordPractice(this,false);this.streak=0;this.charge=0;this.power=false;this.ready=true;this.cooldown=.4;this.elapsed=0;this.events.push({type:'wrong',text:this.question.text,answer:this.question.answer});return false}const available=this.enemies.filter(e=>!e.targeted).sort((a,b)=>b.z-a.z);if(!available.length)return false;recordPractice(this,true);this.streak++;this.charge++;this.power=this.charge>=4;if(this.power)this.charge=0;this.ready=true;this.cooldown=.7;this.elapsed=0;const targets=available.slice(0,this.power?3:1);this.targetX=targets[0].x;for(const enemy of targets){enemy.targeted=true;const shot={id:++this.shotId,targetId:enemy.id,elapsed:0,duration:.65,power:this.power,coins:enemy===targets[targets.length-1]?10:0,fromX:this.x,x:enemy.x,z:enemy.z};this.shots.push(shot);this.events.push({type:'shot',id:shot.id,targetId:enemy.id,power:this.power,x:enemy.x,z:enemy.z})}if(this.power)this.events.push({type:'dash'});return true}
 update(dt){if(!this.active||!Number.isFinite(dt)||dt<=0)return;let remaining=dt;while(remaining>0&&this.active){const step=Math.min(.05,remaining);remaining-=step;this.time+=step;this.elapsed+=step;this.x+=(this.targetX-this.x)*(1-Math.exp(-step*5));this.duration=Math.max(3.8,5.5-this.passed*.12);if(this.ready){this.cooldown-=step;if(this.cooldown<=1e-9){this.ready=false;this.question=this.makeQuestion();this.elapsed=0}}for(const shot of this.shots){shot.elapsed+=step;const enemy=this.enemies.find(e=>e.id===shot.targetId);if(enemy){shot.x=enemy.x;shot.z=enemy.z}if(shot.elapsed+1e-9>=shot.duration){shot.done=true;if(enemy){this.enemies=this.enemies.filter(e=>e.id!==enemy.id);this.passed++;this.level=1+Math.floor(this.passed/4);const coins=shot.coins||0;this.coins+=coins;this.events.push({type:'pass',coins,power:shot.power,passed:this.passed,x:enemy.x,z:enemy.z,targetId:enemy.id});if(this.passed>=this.total){this.active=false;this.events.push({type:'win'});break}}}}this.shots=this.shots.filter(s=>!s.done);if(!this.active)break;for(const enemy of this.enemies)enemy.z+=step/this.duration;const missed=this.enemies.filter(e=>e.z>=1);for(const enemy of missed){this.enemies=this.enemies.filter(e=>e.id!==enemy.id);this.shots=this.shots.filter(s=>s.targetId!==enemy.id);this.hearts--;this.streak=0;this.charge=0;const practiceMiss=recordPractice(this,false,true);this.events.push({type:'miss',x:enemy.x,z:1,targetId:enemy.id,text:this.question.text,answer:this.question.answer});if(practiceMiss&&!this.ready)this.question=this.makeQuestion();if(this.hearts<=0){if(this.timed){this.hearts=3;this.events.push({type:'recharge'})}else{this.hearts=0;this.active=false;this.events.push({type:'over'});break}}}if(this.active)this.fillEnemies()}}
 get progress(){return this.enemies.reduce((n,e)=>Math.max(n,e.z),0)}drain(){const events=this.events;this.events=[];return events}
}return{Flight}});
